"-- ============================================\n-- THE CNPJOTO STREET — Inteligência de Dados\n-- Criação de Base de Dados própria para ML (Formato UCI)\n-- Execute no SQL Editor do Supabase\n-- ============================================\n\n-- 1. Tabela para coletar as sessões dos clientes e alimentar o modelo no futuro\nCREATE TABLE IF NOT EXISTS ml_customer_sessions (\n    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n    customer_id UUID REFERENCES profiles(id) ON DELETE SET NULL, -- Null se for visitante não logado\n    session_id TEXT NOT NULL, -- ID do navegador/cookie da sessão atual\n    \n    -- Features Administrativas (Ex: Painel de conta, perfil)\n    administrative_views INTEGER DEFAULT 0,\n    administrative_duration DECIMAL(10,2) DEFAULT 0.0,\n    \n    -- Features Informativas (Ex: Sobre nós, Política de troca)\n    informational_views INTEGER DEFAULT 0,\n    informational_duration DECIMAL(10,2) DEFAULT 0.0,\n    \n    -- Features de Produto (Ex: Olhou camiseta, olhou calça)\n    product_related_views INTEGER DEFAULT 0,\n    product_related_duration DECIMAL(10,2) DEFAULT 0.0,\n    \n    -- Métricas Analíticas\n    bounce_rate DECIMAL(5,4) DEFAULT 0.0,\n    exit_rate DECIMAL(5,4) DEFAULT 0.0,\n    page_value DECIMAL(10,2) DEFAULT 0.0,\n    \n    -- Contexto Temporal e Tecnológico\n    special_day DECIMAL(3,2) DEFAULT 0.0, -- Quão perto está do dia dos namorados, mães, etc.\n    month TEXT NOT NULL,                  -- 'Jan', 'Feb', etc\n    operating_system INTEGER DEFAULT 1,   -- 1 = Windows, 2 = Mac, 3 = Android, 4 = iOS...\n    browser INTEGER DEFAULT 1,            -- 1 = Chrome, 2 = Safari, 3 = Edge...\n    region INTEGER DEFAULT 1,\n    traffic_type INTEGER DEFAULT 1,       -- 1 = Direto, 2 = Orgânico, 3 = Ads...\n    visitor_type TEXT CHECK (visitor_type IN ('New_Visitor', 'Returning_Visitor', 'Other')),\n    is_weekend BOOLEAN DEFAULT false,\n    \n    -- O TARGET: Fechou a compra no final dessa sessão?\n    revenue BOOLEAN DEFAULT false,\n    \n    created_at TIMES
